def operation(n):
    if n == 0:
        return 0
    d = n % 10
    m = n // 10
    return m + 3 * d

def trace_sequence(start_n, max_steps=1000):
    sequence = [start_n]
    history = {start_n: 0}
    current = start_n
    for i in range(1, max_steps + 1):
        next_n = operation(current)
        if next_n in history:
            start_of_cycle = history[next_n]
            cycle_length = i - start_of_cycle
            return sequence, start_of_cycle, cycle_length

        sequence.append(next_n)
        history[next_n] = i
        current = next_n
    return sequence, None, None

seeds = [1, 2, 5, 10, 11, 20, 50, 100]
results = {}

for s in seeds:
    sequence, start_cycle, cycle_len = trace_sequence(s)
    results[s] = (sequence, start_cycle, cycle_len)

for s, (seq, start, length) in results.items():
    print(f"--- Seed {s} ---")
    print(f"Sequence: {seq}")
    if start is not None:
        print(f"Cycle detected: starts at index {start}, length {length}")
    else:
        print("No cycle found within max_steps.")

